'use strict';
(() => {
const native=!!window.corpDesktop?.isNative&&!!window.chrome?.webview;
function normalize(value){value=String(value).trim();if(/^https?:\/\//i.test(value)){try{return new URL(value).href;}catch{return null;}}if(/^[\w.-]+\.[a-z]{2,}(?:\/[^\s]*)?$/i.test(value))return 'https://'+value;return 'https://www.google.com/search?q='+encodeURIComponent(value);}
function browse(value){const url=normalize(value);if(!url)return;if(native)window.chrome.webview.postMessage({action:'openBrowser',url});else window.open(url,'_blank','noopener,noreferrer');}
if(native){const previous=openApp;openApp=id=>{if(id==='chrome'){browse('https://www.google.com');return;}previous(id);};}
document.addEventListener('keydown',event=>{const target=event.target;if(event.key!=='Enter'||!(target instanceof HTMLInputElement)||!['browserAddress','chromeSearch'].includes(target.id))return;const text=target.value.trim();if(!text||/^(corp|chrome):\/\//i.test(text))return;event.preventDefault();event.stopImmediatePropagation();browse(text);},{capture:true});
// Native discovery runs outside page CORS restrictions and never pulls or starts a model automatically.
window.addEventListener('corp-ollama',event=>{if(!native||typeof state==='undefined')return;const probe=event.detail;state.nativeOllama={available:!!probe.available,installed:!!probe.installed,models:probe.models||[]};if(probe.available&&probe.models?.length){const models=probe.models.map(m=>m.name);if(!state.preferences.ollamaAutoConfigured){state.assistant.model=models.find(m=>/3b|4b|7b|8b/i.test(m))||models[0];state.assistant.mode='ollama';state.preferences.ollamaAutoConfigured=true;}else if(state.assistant.mode==='ollama'&&!models.includes(state.assistant.model))state.assistant.model=models[0];}save();const settingsNode=document.getElementById('settingsOllamaStatus');if(settingsNode&&typeof ollamaStatusText==='function')settingsNode.textContent=ollamaStatusText();const node=document.getElementById('nativeOllamaStatus');if(node)node.textContent=probe.available?`Ollama detected · ${probe.models.length} local model(s)`:probe.installed?'Ollama installed · click to start':'Ollama not detected · offline coach available';});
if(native){window.chrome.webview.postMessage({action:'probeOllama'});const status=document.createElement('button');status.id='nativeOllamaStatus';status.style.cssText='position:absolute;right:22px;top:14px;color:#d9e9f7;font:10px Segoe UI,sans-serif;background:#173c56aa;border:1px solid #d9e9f744;border-radius:4px;padding:8px;cursor:pointer';status.textContent='Checking local Ollama…';status.title='Open installed Ollama, or refresh its status';status.onclick=()=>{const info=state.nativeOllama;if(!info?.available)window.chrome.webview.postMessage({action:'startOllama'});window.chrome.webview.postMessage({action:'probeOllama'});};document.getElementById('desktop')?.append(status);}
window.CorpDesk={...window.CorpDesk,nativeBrowser:native,browseRealPage:browse};
})();
